refentry.refsect1:
&reftitle.description;

 public Yaf_Response_AbstractnullYaf_Controller_Abstract::getResponse



 Retourne l'instance de Yaf_Response_Abstract associée à ce contrôleur.

  &reftitle.examples;

   Exemple avec Yaf_Controller_Abstract::getResponse


<?php
class ProductController extends Yaf_Controller_Abstract
{
    public function apiAction() {
        // construction de la réponse à la main, aucun template n'est nécessaire
        Yaf_Dispatcher::getInstance()->disableView();

        $response = $this->getResponse();
        $response->setHeader("Content-Type", "application/json");
        $response->setBody(json_encode(array("name" => "yaf")));
        // Yaf envoie le corps une fois la boucle de distribution terminée
    }
}
?>
